def is_permutation_polynomial(a3, a1, p):
    # Check if a3*x^3 + a1*x is a permutation polynomial modulo p
    seen = [False] * p
    for x in range(p):
        val = (a3 * (x**3) + a1 * x) % p
        if seen[val]:
            return False
        seen[val] = True
    return True

def count_permutation_polynomials(p):
    count = 0
    for a1 in range(p):
        for a3 in range(p):
            if is_permutation_polynomial(a3, a1, p):
                count += 1
    return count

